#!/usr/bin/env node
/**
 * Build the single-file Worker that gets pasted into the Cloudflare dashboard.
 *
 * The dashboard editor takes ONE file. This Worker is four ES modules plus three
 * JSON files imported from ../data/, so `src/index.js` cannot be pasted in on its
 * own - the imports have nothing to resolve against. wrangler's own dry-run
 * bundles it with the same esbuild a real `wrangler deploy` uses, which keeps the
 * two deploy paths from drifting.
 *
 * The result is committed at dist/resopal-worker.js so it can be copied straight
 * out of GitHub's file view, with no terminal anywhere in the loop. Re-run this
 * after ANY change under worker/src/ or data/ - the JSON is compiled in, which is
 * what pins the deployed odds to the deployed commit.
 *
 *     node worker/bundle.mjs
 */
import { execFileSync } from 'node:child_process';
import { readFileSync, writeFileSync, mkdirSync, rmSync } from 'node:fs';
import path from 'node:path';

const here = import.meta.dirname;
const tmp = path.join(here, '.bundle-tmp');
rmSync(tmp, { recursive: true, force: true });
execFileSync('npx', ['--yes', 'wrangler@4', 'deploy', '--dry-run', '--outdir', tmp],
  { cwd: here, stdio: 'inherit' });

const HEADER = `// resopal-proxy - single-file build of worker/src/*.js.
//
// PASTE THIS over the Worker's code in the Cloudflare dashboard, then Deploy.
// Needs no bindings, no environment variables and no KV.
//
// Generated by \`node worker/bundle.mjs\` - do not edit here, edit worker/src/
// and re-run it. The card pool and pack weights are compiled IN, so a change to
// data/*.json needs a re-bundle too; that is what pins the deployed odds to the
// deployed build.
//
// Routes:
//   /  /health                 liveness
//   /img/<CODE>?w=             palify card art, CORS-enabled, cached at the edge
//   /deck/<uuid>               palify deck page, RSC flight payload
//   /profile/<handle>          palify profile page, RSC flight payload
//   /api/pull?set=&packs=      roll booster packs server-side
//   /api/deck?deck=td01|td02   a named deck
//   /api/resolve               a palify link or a decklist -> card art URLs
//                              GET ?deck= / ?url= / ?list=, or POST the text
//   ...&format=fixed           one 63-character art URL per line, for Resonite

`;
const out = path.join(here, 'dist');
mkdirSync(out, { recursive: true });
const bundled = readFileSync(path.join(tmp, 'index.js'), 'utf8')
  .replace(/^\/\/# sourceMappingURL=.*$/m, '').trimEnd() + '\n';
writeFileSync(path.join(out, 'resopal-worker.js'), HEADER + bundled);
rmSync(tmp, { recursive: true, force: true });
console.log(`\n  worker/dist/resopal-worker.js  ${((HEADER.length + bundled.length) / 1024).toFixed(0)} KB`);
